function validate([positive_feedback, negative_feedback, report, student_id, k]) {
  const word = /^[a-z]{1,100}$/;
  if (positive_feedback.length < 1 || positive_feedback.length > 10000) return 'positive_feedback needs 1 to 10^4 words.';
  if (negative_feedback.length < 1 || negative_feedback.length > 10000) return 'negative_feedback needs 1 to 10^4 words.';
  if (!positive_feedback.every(w => word.test(w)) || !negative_feedback.every(w => word.test(w))) return 'Feedback words have 1 to 100 lowercase letters.';
  const positive = new Set(positive_feedback);
  if (negative_feedback.some(w => positive.has(w))) return 'No word may be both positive and negative.';
  const n = report.length;
  if (n < 1 || n > 10000) return 'report needs 1 to 10^4 sentences.';
  if (student_id.length !== n) return 'report and student_id must have the same length.';
  if (report.some(r => r.length > 100 || !/^[a-z]+( [a-z]+)*$/.test(r))) return 'Each report has 1 to 100 characters: lowercase words separated by single spaces.';
  if (student_id.some(id => !Number.isInteger(id) || id < 1 || id > 1000000000)) return 'Student IDs are between 1 and 10^9.';
  if (new Set(student_id).size !== n) return 'Student IDs must be distinct.';
  if (!Number.isInteger(k) || k < 1 || k > n) return 'k is between 1 and the number of reports.';
  return null;
}

