function topStudents(positive_feedback, negative_feedback, report, student_id, k) {
  const positive = new Set(positive_feedback);
  const negative = new Set(negative_feedback);
  const students = [];

  for (let i = 0; i < report.length; i++) {
    let points = 0;
    for (const word of report[i].split(' ')) {
      if (positive.has(word)) {
        points += 3;
      } else if (negative.has(word)) {
        points -= 1;
      }
    }
    students.push([points, student_id[i]]);
  }

  students.sort((a, b) => b[0] - a[0] || a[1] - b[1]);
  return students.slice(0, k).map(([, id]) => id);
}

