function topStudents(positive_feedback, negative_feedback, report, student_id, k) {
  // Score with plain list searches, then pick the best remaining student k times.
  const score = report.map(text => {
    let total = 0;
    for (const word of text.split(' ')) {
      if (positive_feedback.includes(word)) total += 3;
      if (negative_feedback.includes(word)) total -= 1;
    }
    return total;
  });
  const used = new Array(report.length).fill(false);
  const result = [];
  for (let round = 0; round < k; round++) {
    let pick = -1;
    for (let i = 0; i < report.length; i++) {
      if (used[i]) continue;
      if (pick === -1 || score[i] > score[pick] || (score[i] === score[pick] && student_id[i] < student_id[pick])) pick = i;
    }
    used[pick] = true;
    result.push(student_id[pick]);
  }
  return result;
}

