function generate(rand, size) {
  const large = size === 'large';
  const int = m => Math.floor(rand() * m);
  const letters = large ? 6 : 3;
  const randomWord = () => { let w = ''; const len = 1 + int(large ? 5 : 3); for (let i = 0; i < len; i++) w += String.fromCharCode(97 + int(letters)); return w; };
  // A pool of distinct words, split into praising, critical and neutral ones.
  const pool = new Set();
  const poolSize = large ? 600 : 3 + int(5);
  for (let tries = 0; pool.size < poolSize && tries < 10000; tries++) pool.add(randomWord());
  const words = [...pool];
  const positiveCount = 1 + int(Math.max(1, Math.floor(words.length / 3)));
  const negativeCount = 1 + int(Math.max(1, Math.floor(words.length / 3)));
  const positive_feedback = words.slice(0, positiveCount);
  const negative_feedback = words.slice(positiveCount, positiveCount + negativeCount);
  const n = large ? 2000 : 1 + int(6);
  const report = [];
  for (let i = 0; i < n; i++) {
    const parts = [];
    const target = large ? 20 + int(80) : 1 + int(12);
    for (;;) {
      const w = rand() < 0.1 ? randomWord() : words[int(words.length)];
      const length = parts.reduce((s, p) => s + p.length + 1, 0) + w.length;
      if (parts.length && length > target) break;
      parts.push(w);
    }
    report.push(parts.join(' '));
  }
  const ids = new Set();
  const idRange = large || rand() < 0.3 ? 1000000000 : 3 * n;
  while (ids.size < n) ids.add(1 + int(idRange));
  const student_id = [...ids];
  const k = rand() < 0.3 ? n : 1 + int(n);
  return [positive_feedback, negative_feedback, report, student_id, k];
}
